using System;
using System.IO;
using System.Drawing;
using System.Collections.Generic;
using System.Windows.Forms;

namespace LoopPedal {
partial class Pedal {
 readonly MidiMap midiMap=new MidiMap();readonly Dictionary<string,Button> midiButtons=new Dictionary<string,Button>();MidiInput midiInput;Form midiWindow;Label midiInfo;StudioChoice midiTarget;bool midiReady;
 string MidiPath{get{return Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Agent-Looper-MIDI.xml");}}
 void InitMidi(){midiMap.Trigger=DispatchMidiAction;midiMap.Value=ApplyMidiValue;midiMap.Learned=action=>{SaveMidi();if(midiInfo!=null&&!midiInfo.IsDisposed)midiInfo.Text=action+" · "+midiMap.Bindings[action];status.Text="MIDI · "+action+" · "+midiMap.Bindings[action];};try{if(File.Exists(MidiPath))midiMap.Load(MidiPath);else{string legacy=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Strata-MIDI.xml");if(File.Exists(legacy))midiMap.Load(legacy);}if(!previewMode&&!string.IsNullOrEmpty(midiMap.DeviceName)){int device=Array.IndexOf(MidiInput.Names(),midiMap.DeviceName);if(device>=0)midiInput=new MidiInput(device);}}catch(Exception e){status.Text=e.Message;}midiReady=true;}
 void PollMidi(){if(!midiReady||midiInput==null)return;int packed,limit=128;while(limit-->0&&midiInput.TryRead(out packed))midiMap.Handle(packed);}
 void SaveMidi(){try{midiMap.Save(MidiPath);}catch(Exception e){status.Text="MIDI settings · "+e.Message;}}
 void RegisterMidi(string action,Button button){midiButtons[action]=button;button.AccessibleDescription="Right-click for MIDI Learn";var menu=new ContextMenuStrip{Renderer=new StudioMenuRenderer(),ShowImageMargin=false,BackColor=Skin.Ink,ForeColor=Color.WhiteSmoke};menu.Items.Add("MIDI Learn",null,(s,e)=>LearnMidi(action));menu.Items.Add("Clear MIDI",null,(s,e)=>{midiMap.Bindings.Remove(action);if(midiMap.LearnTarget==action)midiMap.LearnTarget=null;SaveMidi();status.Text="MIDI cleared · "+action;});button.ContextMenuStrip=menu;button.Disposed+=(s,e)=>menu.Dispose();}
 void RegisterMidiKnob(string action,Knob knob){RegisterMidiControl(action,knob);}
 void RegisterMidiControl(string action,Control knob){knob.Tag=action;knob.AccessibleDescription="Right-click for MIDI CC Learn";var menu=new ContextMenuStrip{Renderer=new StudioMenuRenderer(),ShowImageMargin=false,BackColor=Skin.Ink,ForeColor=Color.WhiteSmoke};menu.Items.Add("MIDI CC Learn",null,(s,e)=>LearnMidi(action));menu.Items.Add("Clear MIDI",null,(s,e)=>{midiMap.Bindings.Remove(action);if(midiMap.LearnTarget==action)midiMap.LearnTarget=null;SaveMidi();});knob.ContextMenuStrip=menu;knob.Disposed+=(s,e)=>menu.Dispose();}
 IEnumerable<Knob> MidiKnobs(Control parent){foreach(Control child in parent.Controls){var k=child as Knob;if(k!=null)yield return k;else foreach(var nested in MidiKnobs(child))yield return nested;}}
 void ApplyMidiValue(string target,int value){float normalized=value/127f;if(target.StartsWith("FX.")){int id;bool bankB=target.StartsWith("FX.B.");if(!int.TryParse(target.Substring(bankB?5:3),out id)||id<0||id>25)return;if(bankB&&id!=0&&id!=2&&id!=5&&id!=18)return;FxParameters.Set(loopers[bankB?1:0].Fx,id,normalized);if(fxSurface!=null)foreach(var k in MidiKnobs(fxSurface)){string key=k.Tag as string;if(key!=null&&key.StartsWith("FX.")){bool b=key.StartsWith("FX.B.");int kind=int.Parse(key.Substring(b?5:3));k.Value=(int)(FxParameters.Get(loopers[b?1:0].Fx,kind)*1000);k.Invalidate();}fxSurface.Invalidate(true);}return;}
 foreach(var knob in MidiKnobs(this))if((knob.Tag as string)==target){knob.Value=knob.Min+(int)Math.Round(normalized*(knob.Max-knob.Min));if(knob.Commit!=null)knob.Commit(knob.Value);knob.Invalidate();return;}}
 void LearnMidi(string action){midiMap.LearnTarget=action;midiMap.ResetEdges();if(midiInput==null){ShowMidi();if(midiTarget!=null)midiTarget.SelectedItem=action;}if(midiInfo!=null&&!midiInfo.IsDisposed)midiInfo.Text="LEARNING · "+action+(MidiMap.Continuous(action)?" · MOVE CC":"");status.Text="MIDI LEARN · "+action;}
 void ShowMidi(){if(midiWindow!=null&&!midiWindow.IsDisposed){midiWindow.Activate();return;}midiWindow=new Form{Text="Agent Looper / MIDI",Size=new Size(440,220),FormBorderStyle=FormBorderStyle.FixedToolWindow,StartPosition=FormStartPosition.CenterParent,ShowInTaskbar=false,BackColor=Skin.Ink,ForeColor=Color.WhiteSmoke,Font=Font};var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(16),WrapContents=true};midiWindow.Controls.Add(flow);flow.Controls.Add(new Label{Text="INPUT",Width=390,Height=18,ForeColor=Skin.Muted});var devices=new StudioChoice{Width=390,DropDownStyle=ComboBoxStyle.DropDownList,BackColor=Skin.Panel,ForeColor=Color.WhiteSmoke,FlatStyle=FlatStyle.Flat};devices.Items.Add("OFF");string[] names=MidiInput.Names();foreach(string name in names)devices.Items.Add(name);devices.SelectedIndex=Math.Max(0,Array.IndexOf(names,midiMap.DeviceName)+1);devices.SelectedIndexChanged+=(s,e)=>{try{if(midiInput!=null){midiInput.Dispose();midiInput=null;}midiMap.ResetEdges();midiMap.DeviceName=devices.SelectedIndex>0?devices.SelectedItem.ToString():"";if(devices.SelectedIndex>0)midiInput=new MidiInput(devices.SelectedIndex-1);SaveMidi();}catch(Exception ex){status.Text=ex.Message;if(midiInfo!=null)midiInfo.Text=ex.Message;}};flow.Controls.Add(devices);midiTarget=new StudioChoice{Width=190,DropDownStyle=ComboBoxStyle.DropDownList,BackColor=Skin.Panel,ForeColor=Color.WhiteSmoke,FlatStyle=FlatStyle.Flat,Margin=new Padding(3,12,3,3)};foreach(string action in midiButtons.Keys)midiTarget.Items.Add(action);for(int i=0;i<26;i++)if(FxParameters.Canonical(i)==i)midiTarget.Items.Add("FX."+i);foreach(int kind in new[]{0,2,5,18})midiTarget.Items.Add("FX.B."+kind);midiTarget.Items.Add("MASTER");foreach(var k in MidiKnobs(this)){string key=k.Tag as string;if(key!=null&&key.Contains(".Layer.")&&!midiTarget.Items.Contains(key))midiTarget.Items.Add(key);}if(midiTarget.Items.Count>0)midiTarget.SelectedIndex=0;flow.Controls.Add(midiTarget);var learn=Btn("LEARN",()=>LearnMidi(midiTarget.SelectedItem.ToString()));learn.Margin=new Padding(3,8,3,3);flow.Controls.Add(learn);var clear=Btn("CLEAR",()=>{if(midiTarget.SelectedItem!=null){midiMap.Bindings.Remove(midiTarget.SelectedItem.ToString());SaveMidi();midiInfo.Text="CLEARED";}});clear.Size=new Size(75,32);clear.Margin=new Padding(3,8,3,3);flow.Controls.Add(clear);midiInfo=new Label{Text="",Width=390,Height=30,ForeColor=Skin.Mint};flow.Controls.Add(midiInfo);midiWindow.FormClosed+=(s,e)=>{midiMap.LearnTarget=null;midiInfo=null;midiTarget=null;};midiWindow.Show(this);}
 void CloseMidi(){if(midiWindow!=null&&!midiWindow.IsDisposed)midiWindow.Close();if(midiInput!=null){midiInput.Dispose();midiInput=null;}}
}
}



